/**
 * The `workbench` page type: the project's workbench, generated by @saasreport/widgets from widgets.spec.json (a workbench
 * widget exported as `workbench`) and rendered by @saasreport/workbench. The site adds no content.
 *
 *   { type: "workbench", path: "/workbench/", generated: <widgets.generated.json>,
 *     content: { <locale>: { meta?: { title, description, ogImage }, bar?: [links], chrome?: { …runtime words } } } }
 *
 * Styles: the theme's workbench.css (rendered with the project's tokens); script: workbench.js (the runtime).
 */
import { workbenchChunks, workbenchProblems, chromeFor } from "../../../workbench/src/index.js";
import { innerPage, webPageLd, crumbsLd } from "./shell.js";
import { GENERATED_SCHEMA } from "./widgets.js";

export function checkWorkbenchPage(page, codes = []) {
  const p = [], g = page.generated;
  if (!g || g.schema !== GENERATED_SCHEMA) return [`pages[${page.path}]: generated must be a ${GENERATED_SCHEMA} file (kit widgets build)`];
  for (const code of codes) {
    const def = g.exports?.workbench?.[code];
    if (!def) p.push(`pages[${page.path}]: no workbench export for ${code} (spec: build.exports { as: "workbench" })`);
    else for (const q of workbenchProblems(def)) p.push(`pages[${page.path}] (${code}): ${q}`);
  }
  return p;
}

export function renderWorkbenchPage(page, ctx) {
  const code = ctx.L.code, c = page.content?.[code] || {}, def = page.generated.exports.workbench[code];
  const S = chromeFor(code, c.chrome), title = c.meta?.title || def.title, description = c.meta?.description || def.intro || title;
  const u = ctx.url + ctx.pathOf(page.path), chunks = workbenchChunks(def, S);
  return {
    "index.html": innerPage(ctx, {
      path: page.path, title, description, ogImage: c.meta?.ogImage,
      graph: [webPageLd({ name: title, description, url: u, ctx, extra: { mainEntity: { "@type": "WebApplication", name: title, url: u, applicationCategory: "FinanceApplication", operatingSystem: "Any", inLanguage: ctx.L.intl } } }), crumbsLd([[ctx.chrome.strings.home, ctx.homeUrl], [title, u]])],
      styles: ["/workbench.css"], scripts: ["/workbench.js"], bodyClass: "tpage wb-body", body: chunks.first + chunks.panes.join("") + chunks.last, generator: "@saasreport/workbench", bar: c.bar,
    }),
  };
}
